// Variant structs
// An argument was malformed or out of range. Retrying with the same
// arguments fails the same way.
type WalletErrorInvalidArgument struct {
	Message string
}

// An argument was malformed or out of range. Retrying with the same
// arguments fails the same way.
func NewWalletErrorInvalidArgument(
	message string,
) *WalletError {
	return &WalletError{err: &WalletErrorInvalidArgument{
		Message: message}}
}

func (e WalletErrorInvalidArgument) destroy() {
	FfiDestroyerString{}.Destroy(e.Message)
}

func (err WalletErrorInvalidArgument) Error() string {
	return fmt.Sprint("InvalidArgument",
		": ",

		"Message=",
		err.Message,
	)
}

func (self WalletErrorInvalidArgument) Is(target error) bool {
	return target == ErrWalletErrorInvalidArgument
}

